    def can_achieve(v, target, steps, max_change):
        if steps == 0:
            return v == target
        return any(
            can_achieve(v + delta, target, steps - 1, max_change)
            for delta in range(-max_change, max_change + 1)
            if 1 <= v + delta <= 100
        )

    # Try to distribute the speeds as evenly as possible within the constraints
    total_length = 0
    for i in range(t):
        if i == 0:
            speed = v1
        elif i == t - 1:
            speed = v2
        else:
            # Calculate the speed that can be used in the current second
            for delta in range(-d, d + 1):
                if i == 1:
                    next_speed = v2 - delta
                else:
                    next_speed = min(max(v1, speed + delta), 100)

                if can_achieve(speed, next_speed, t - i - 1, d):
